// Coaching describes public rules and visible state; it never reads an opponent’s secret.
export const MODES={relaxed:'Learn',standard:'Standard',hard:'Expert'};
export const LESSONS={
virus:{steps:['Read the verified journalist report in the log.','Select a seat; interview before deciding whether to shoot.','Choose a research candidate, then end the round.'],example:'A Citizen claim can be a lie. A journalist report is verified. Shooting a verified Terrorist is safer than shooting an unverified claimant.',warning:'You play the neutral Officer: eliminate both Terrorists. A citizen cure does not win your mission.',modes:['Reports prioritize Terrorists; hidden bullets wait until round 3.','One verified report each round; hidden bullets wait until round 3.','More frequent hidden bullets from round 3.']},
race:{steps:['Choose a personal rule before the first roll.','Roll, or spend an escape ticket if imprisoned.','At an office, choose a benefit before the bots continue.'],example:'With rule 1, any player going to prison gives you an escape ticket. Save tickets until you are imprisoned.',warning:'An escape ticket frees you but uses this turn. The first finisher wins in scored modes.',modes:['Start with two tickets; a top-two finish succeeds.','Start without tickets; finish first.','Same race rules; finish first. Dice remain random.']},
number:{steps:['Choose two different players and a ticket type.','Build a connected notebook, including contacts between bots.','Combine clues, then submit your own number and optional others.'],example:'If You + Mira = 70, You + Sage = 90, and Mira + Sage = 80, your number is (70 + 90 − 80) ÷ 2 = 40.',warning:'Sums at 20 or below and 180 or above are ranges. Repeating a contact gives no new information.',modes:['12 shared contacts; candidate helper.','8 shared contacts; candidate helper.','6 shared contacts; candidate helper.']},
zoo:{steps:['Read your animal sequence and doubling condition.','Choose a lot and submit a sealed bid. The smaller group total wins.','If you are its highest bidder, drop all four tiles into columns.'],example:'A totals 5 credits and B totals 9: A wins. The highest individual bidder within A controls placement. Everyone pays, including B.',warning:'A tied auction refunds bids and repeats the same lots. Tiles fall to the lowest open cell.',modes:['Bots bid 1–4 with random lot choices.','Bots favor lots matching their own patterns.','Bots can bid up to 9; watch your budget.']},
grass:{steps:['Select a shape, then rotate or reflect it.','Hover over the board to preview its top-left anchor.','Place beside your green territory; build a filled square.'],example:'A 3×3 square needs all nine interior cells. A long strip with more total cells still loses to a larger filled square.',warning:'Touch your own land along an edge. Never touch rival land along an edge. Diagonal contact alone does not connect your land.',modes:['Bot placements have more variation.','Bot favors squares and compact territory.','Bot consistently favors its best one-turn placement.']},
equation:{steps:['Choose the order of all four number cards.','Use +, − and ÷ exactly once; division happens first.','Pick Low or High, choose a wager, then show down.'],example:'7 + 9 ÷ 3 − 2 = 8. That is distance 7 from Low (1), or distance 12 from High (20).',warning:'This is an equation-training variant. The show also had staged betting, special cards, Swing and card tie-breakers.',modes:['Each bot samples 6 expressions.','Each bot samples 24 expressions.','Each bot searches all 144 arrangements.']},
puzzle:{steps:['Select a lettered piece from the tray.','Rotate or reflect; click its top-left anchor on the board.','Fill every cell. Click an occupied piece to lift it.'],example:'A shape with an empty top-left corner still uses its bounding box as the anchor. The preview in the tray shows its orientation.',warning:'The boards grow each round. A placement can fit now but block the remaining pieces. Standard and Expert also scramble the initial piece orientations.',modes:['3–4 pieces on 4×3 then 4×4 boards; unlimited hints; untimed.','4 → 6 → 9 pieces on 4×4, 6×4 and 6×6 boards; two hints; untimed.','9 → 12 → 16 pieces on 6×6, 8×6 and 8×8 boards; one hint; three minutes per board.']},
memory:{steps:['Study counts, colors, text and the clock.','Hide the scene when ready.','Answer ten questions; use a teammate pass when unsure.'],example:'Count the books separately from their colors. For the clock, remember the short hour hand rather than the long minute hand.',warning:'Standard and Expert end on one wrong answer. Teammate passes are guaranteed help in this solo edition.',modes:['Untimed study; review scene during questions; mistakes teach.','90 seconds to study; two passes.','30 seconds to study; one pass.']},
words:{steps:['Read the category and available letter tiles.','Build three different words from the accepted dictionary.','Use every letter; return a word if the remainder gets stuck.'],example:'CAT + DOG + OWL uses C A T D O G O W L. A different valid word may leave an impossible remainder, so returning words is part of the puzzle.',warning:'Only the visible dictionary is accepted. Your teammate contributes one word per round.',modes:['Words have at most four letters.','Mixed word lengths.','Words have at least four letters.']},
scale:{steps:['Choose an unknown mineral and a reference mass.','Use < or > to halve its remaining range.','Record an equal weighing, then declare all five weights.'],example:'Gold > 10g narrows it to 11–20g. Compare to 15g next. Repeat until one value remains, then confirm equality.',warning:'This is a calibration lesson: reusable pans and reference grams are solo changes. The show used accumulating, nonremovable minerals.',modes:['40 weighings; practice undo.','26 weighings; wrong declarations cost one.','22 weighings; wrong declarations cost one.']},
montage:{steps:['Start the sequence and remember each exact portrait.','Choose New face if it has not appeared this round.','Buzz only when the whole portrait repeats.'],example:'The same glasses are not enough. Compare hair, shirt, complexion and expression as a group.',warning:'A false buzz costs one mistake and keeps the portrait on screen. Missing a repeat ends scored play; ten false buzzes also ends it.',modes:['Manual advance; missed repeats become review rounds.','Five seconds per portrait; no random teammate rescue.','Broadcast timing: three seconds per portrait.']},
three:{steps:['Place a red reserve piece, or choose Move exposed piece.','Moving uses an exposed red piece and an adjacent destination.','Help any teammate make three; prevent blue from making three.'],example:'Covering a blue top piece can block a line. Moving red away can uncover a blue piece and accidentally give the guest a line.',warning:'Only top colors count. Stacks hold at most three. Diagonal moves and diagonal lines count.',modes:['Complete one cooperative round.','Keep the guest from winning four rounds.','Four rounds with more consistent bot tactics.']},
morris:{steps:['Place nine ivory stones, one per turn.','Form a connected line of three to capture a dark stone.','After placement, slide along edges; with three stones you may fly.'],example:'Three stones on one side of a square form a mill. Capture an opponent outside a mill if one is available.',warning:'Win by reducing the opponent to two stones or leaving no legal move. The connecting lines define legal movement.',modes:['More varied bot decisions; practice undo.','Bot looks for mills and immediate threats.','Bot consistently takes its best one-turn tactic.']},
hex:{steps:['Study the numbers at their lettered positions.','Hide them to reveal the target.','Choose three consecutive cells in a straight line that sum to the target.'],example:'A line with 3, 7 and 5 totals 15. Bent triples do not count, even if their sum is correct.',warning:'Correct +1; wrong sum or repeated answer −1. Invalid geometry gets a free correction. Ending a round gives no hidden bonus to the bot.',modes:['Numbers stay visible; bot does not claim lines.','60-second study; bot tries at most three lines per round.','30-second study; bot tries at most five lines per round.']},
gomoku:{steps:['Place an ivory stone on an empty intersection.','Track your stones and the dealer’s replies.','Connect five in a straight line while blocking threats.'],example:'Four dark stones with an open end threaten an immediate win. Block that end before extending your own line.',warning:'Scored modes hide all but the latest pair of moves. Occupied intersections remain unavailable.',modes:['All stones stay face-up; practice undo.','Latest pair stays visible; tactical bot.','Latest pair visible; more consistent tactical bot.']}
};
export function studyTime(id,mode){return mode==='hard'?30:id==='memory'?90:id==='hex'?60:30;}
export function turnGuide(s){
const steps=LESSONS[s.id].steps;let index=0;
switch(s.id){
case 'virus':index=s.shot||!s.talks?2:s.asked.length?1:0;break;
case 'race':index=s.phase==='setup'?0:s.office?2:1;break;
case 'number':index=s.left<=2?2:s.contacts.length?1:0;break;
case 'zoo':index=s.phase==='place'?2:1;break;
case 'grass':index=s.rot||s.flip?2:0;break;
case 'equation':index=s.order.length===4?2:s.order.length?1:0;break;
case 'puzzle':index=s.board.some(x=>x!==-1)?2:1;break;
case 'memory':index=s.phase==='quiz'?2:0;break;
case 'words':index=s.used.length?2:1;break;
case 'scale':index=s.balanced&&s.bounds.every(([a,b])=>a===b)?2:s.history.length?1:0;break;
case 'montage':index=s.phase==='ready'?0:s.seen.includes(s.faces[s.index])?1:1;break;
case 'three':index=s.selected>=0?1:0;break;
case 'morris':index=s.capture?1:s.reserve[0]?0:2;break;
case 'hex':index=s.phase==='study'?0:2;break;
case 'gomoku':index=0;break;
}
return {steps,index,text:steps[index]};
}
